const REGIONAL_QL_IDS: Readonly<Record<string, readonly [string, string]>> = {
  "WGE-001-CP024": ["WGE-001-CP024-QL-REGION-ID-V1", "WGE-001-CP024-QL-REGION-MATCH-V1"],
  "WGE-001-CP025": ["WGE-001-CP025-QL-REGION-ID-V1", "WGE-001-CP025-QL-REGION-MATCH-V1"],
  "WGE-001-CP026": ["WGE-001-CP026-QL-REGION-ID-V1", "WGE-001-CP026-QL-REGION-MATCH-V1"],
  "WGE-001-CP027": ["WGE-001-CP027-QL-REGION-ID-V1", "WGE-001-CP027-QL-REGION-MATCH-V1"],
  "WGE-001-CP028": ["WGE-001-CP028-QL-REGION-ID-V1", "WGE-001-CP028-QL-REGION-MATCH-V1"],
  "WGE-001-CP029": ["WGE-001-CP029-QL-REGION-ID-V1", "WGE-001-CP029-QL-REGION-MATCH-V1"],
  "WGE-001-CP030": ["WGE-001-CP030-QL-REGION-ID-V1", "WGE-001-CP030-QL-REGION-MATCH-V1"],
  "WGE-001-CP031": ["WGE-001-CP031-QL-REGION-ID-V1", "WGE-001-CP031-QL-REGION-MATCH-V1"],
};

const bumpDifficulty = (difficulty: RegionalDifficulty): RegionalDifficulty =>
  difficulty === 'Easy' ? 'Medium' : 'Hard';

function peersFor(target: RegionalFact): readonly RegionalFact[] {
  const peers = REGIONAL_FACTS.filter(f => f.cpId === target.cpId && f.category === target.category);
  if (peers.length !== 4) throw new Error(`Regional pool category must contain exactly four facts: ${target.cpId}/${target.category}`);
  return peers;
}

function shuffledOptions(target: RegionalFact, values: readonly LocalizedValue[], family: string) {
  const id = `${target.cpId}-Q-VP-REGION-${family}-${target.key}`.toUpperCase();
  const order = deterministicShuffle([0, 1, 2, 3], `${id}:option-order`);
  const options = (language: Language) => order.map(i => values[i]![language]);
  return { id, order, options };
}

function makeIdentifyQuestion(target: RegionalFact): WorldGeographyQuestion {
  const peers = peersFor(target);
  const ordered = [target, ...peers.filter(f => f.key !== target.key)];
  const { id, order, options } = shuffledOptions(target, ordered.map(f => f.feature), 'IDENTIFY');
  const qlId = REGIONAL_QL_IDS[target.cpId]![0];
  return {
    id,
    cpId: target.cpId,
    objective: `variable-regional-identify-${target.key}`,
    difficulty: target.difficulty,
    sourceIds: [...target.sourceIds],
    correctIndex: order.indexOf(0),
    authoringReviewApproved: true,
    generationSource: `${target.cpId}-REGIONAL-VARIABLE-POOL-V1`,
    qlId,
    locales: {
      en: { stem: target.stem.en, options: options('en'), explanation: `${target.feature.en} — ${target.match.en}.` },
      hi: { stem: target.stem.hi, options: options('hi'), explanation: `${target.feature.hi} — ${target.match.hi}।` },
      pa: { stem: target.stem.pa, options: options('pa'), explanation: `${target.feature.pa} — ${target.match.pa}।` },
    },
  };
}

function makeMatchQuestion(target: RegionalFact): WorldGeographyQuestion {
  const peers = peersFor(target);
  const ordered = [target, ...peers.filter(f => f.key !== target.key)];
  const mismatched = [
    { feature: ordered[0]!.feature, match: ordered[0]!.match },
    { feature: ordered[1]!.feature, match: ordered[2]!.match },
    { feature: ordered[2]!.feature, match: ordered[3]!.match },
    { feature: ordered[3]!.feature, match: ordered[1]!.match },
  ];
  const pairValues = mismatched.map(p => ({
    en: `${p.feature.en} — ${p.match.en}`,
    hi: `${p.feature.hi} — ${p.match.hi}`,
    pa: `${p.feature.pa} — ${p.match.pa}`,
  }));
  const { id, order, options } = shuffledOptions(target, pairValues, 'MATCH');
  const qlId = REGIONAL_QL_IDS[target.cpId]![1];
  const stem = {
    en: 'Which geographical feature–description pair is correctly matched?',
    hi: 'कौन-सा भौगोलिक विशेषता–विवरण युग्म सही सुमेलित है?',
    pa: 'ਕਿਹੜਾ ਭੂਗੋਲਿਕ ਵਿਸ਼ੇਸ਼ਤਾ–ਵੇਰਵਾ ਜੋੜ ਸਹੀ ਮਿਲਾਇਆ ਗਿਆ ਹੈ?',
  };
  return {
    id,
    cpId: target.cpId,
    objective: `variable-regional-match-${target.key}`,
    difficulty: bumpDifficulty(target.difficulty),
    sourceIds: [...new Set(ordered.flatMap(f => f.sourceIds))],
    correctIndex: order.indexOf(0),
    authoringReviewApproved: true,
    generationSource: `${target.cpId}-REGIONAL-VARIABLE-POOL-V1`,
    qlId,
    locales: {
      en: { stem: stem.en, options: options('en'), explanation: `${target.feature.en} — ${target.match.en}.` },
      hi: { stem: stem.hi, options: options('hi'), explanation: `${target.feature.hi} — ${target.match.hi}।` },
      pa: { stem: stem.pa, options: options('pa'), explanation: `${target.feature.pa} — ${target.match.pa}।` },
    },
  };
}

export const WGE_REGIONAL_VARIABLE_POOL_QUESTIONS_V1: readonly WorldGeographyQuestion[] =
  Object.freeze(REGIONAL_FACTS.flatMap(f => [makeIdentifyQuestion(f), makeMatchQuestion(f)]));

export const WGE_REGIONAL_VARIABLE_POOL_QL_IDS_V1: readonly string[] =
  Object.freeze(Object.values(REGIONAL_QL_IDS).flatMap(ids => [...ids]));
